// Only size image markup generated by RemoteImageLoader after explicit loading.
// Sanitized remote placeholders and all other content remain untouched.
function fitImages(html, availableWidth) {
    const limit = Math.max(1, Math.floor(availableWidth))
    return String(html).replace(/<img width="(\d+)" height="(\d+)" src="(data:[^"]+)">/g,
        function(tag, width, height, source) {
            const w = Number(width), h = Number(height)
            if (w <= limit || w <= 0 || h <= 0) return tag
            return '<img width="' + limit + '" height="' + Math.max(1, Math.round(h * limit / w))
                + '" src="' + source + '">'
        })
}
